const gray={1:['0','1'],2:['00','01','11','10']};
const colors=['#e49a62','#73b7bd','#ac91c7','#d0b84e','#d8757e','#6eb181'];
let n=4, values=Array(16).fill('0'), lastGroups=[];
const $=s=>document.querySelector(s);
const vars=()=>['A','B','C','D'].slice(0,n);
function bits(i){return i.toString(2).padStart(n,'0')}
function dims(){return n===2?[2,2]:n===3?[2,4]:[4,4]}
function indexAt(r,c){const [rows,cols]=dims();const rb=gray[Math.log2(rows)][r],cb=gray[Math.log2(cols)][c];return parseInt(rb+cb,2)}
function renderMap(){const [rows,cols]=dims(), rowN=Math.log2(rows), labels=vars();let h=`<div class="axis corner">${labels.slice(0,rowN).join('')} ╲ ${labels.slice(rowN).join('')}</div>`;for(let c=0;c<cols;c++)h+=`<div class="axis">${gray[Math.log2(cols)][c]}</div>`;for(let r=0;r<rows;r++){h+=`<div class="axis">${gray[Math.log2(rows)][r]}</div>`;for(let c=0;c<cols;c++){let i=indexAt(r,c);h+=`<button class="cell" data-i="${i}" data-v="${values[i]}">${values[i]}<small>m${i}</small></button>`}}$('#mapWrap').style.setProperty('--rows',rows);$('#mapWrap').style.setProperty('--cols',cols);$('#mapWrap').innerHTML=`<div class="kmap">${h}</div>`;document.querySelectorAll('.cell').forEach(b=>b.onclick=()=>{values[+b.dataset.i]=values[+b.dataset.i]==='0'?'1':values[+b.dataset.i]==='1'?'X':'0';renderMap();hideResults()})}
function combine(a,b){let d=0,out='';for(let i=0;i<a.length;i++){if(a[i]!==b[i]){if(a[i]==='-'||b[i]==='-')return null;d++;out+='-'}else out+=a[i]}return d===1?out:null}
function primes(on,dc=[]){let terms=[...new Set([...on,...dc])].map(i=>({p:bits(i),covers:new Set([i])})),all=[];while(terms.length){let used=new Set(),next=new Map();for(let i=0;i<terms.length;i++)for(let j=i+1;j<terms.length;j++){let p=combine(terms[i].p,terms[j].p);if(p){used.add(i);used.add(j);let cv=new Set([...terms[i].covers,...terms[j].covers]);if(next.has(p))cv=new Set([...next.get(p).covers,...cv]);next.set(p,{p,covers:cv})}}terms.forEach((t,i)=>{if(!used.has(i)&&[...t.covers].some(x=>on.includes(x)))all.push(t)});terms=[...next.values()]}let uniq=new Map(all.map(x=>[x.p,x]));return [...uniq.values()]}
function chooseCover(on,ps){if(!on.length)return[];let best=null;const max=1<<ps.length;if(ps.length>18)return ps;for(let mask=1;mask<max;mask++){let chosen=[],covered=new Set(),lits=0;for(let i=0;i<ps.length;i++)if(mask>>i&1){chosen.push(ps[i]);lits+=ps[i].p.replaceAll('-','').length;ps[i].covers.forEach(x=>covered.add(x))}if(on.every(x=>covered.has(x))&&(!best||chosen.length<best.chosen.length||chosen.length===best.chosen.length&&lits<best.lits))best={chosen,lits}}return best?.chosen||[]}
function term(p,pos=false){let out=[];p.split('').forEach((b,i)=>{if(b==='-')return;let v=vars()[i];if(pos)out.push(b==='0'?v:`${v}̄`);else out.push(b==='1'?v:`${v}̄`)});return pos?`(${out.join(' + ')})`:out.join('')||'1'}
function solveSet(target,pos=false){const dc=values.map((v,i)=>v==='X'?i:null).filter(i=>i!==null);if(!target.length)return pos?'1':'0';if(target.length+dc.length===2**n)return pos?'0':'1';let selected=chooseCover(target,primes(target,dc));return {selected,text:selected.map(x=>term(x.p,pos)).join(pos?' · ':' + ')} }
function solve(){const ones=values.map((v,i)=>v==='1'?i:null).filter(i=>i!==null),zeros=values.map((v,i)=>v==='0'?i:null).filter(i=>i!==null);let sop=solveSet(ones),pos=solveSet(zeros,true);$('#sopResult').textContent=typeof sop==='string'?sop:sop.text;$('#posResult').textContent=typeof pos==='string'?pos:pos.text;lastGroups=typeof sop==='string'?[]:sop.selected;renderGroups();renderTruth();$('#readResult').textContent=ones.length?`Cubre los minterms ${ones.join(', ')} usando ${lastGroups.length||1} ${lastGroups.length===1?'grupo':'grupos'}.`:'No hay unos: la función siempre vale 0.';$('#results').classList.remove('hidden');document.querySelectorAll('.step')[2].classList.add('active');setTimeout(()=>$('#results').scrollIntoView({behavior:'smooth',block:'start'}),80)}
function renderGroups(){let h='';lastGroups.forEach((g,k)=>{let cells=[...g.covers].filter(i=>values[i]!=='0').sort((a,b)=>a-b);h+=`<div class="group-item"><i class="group-swatch" style="--group:${colors[k%colors.length]}"></i><div><b>Grupo ${k+1}: ${term(g.p)}</b><br><span>Celdas ${cells.map(x=>'m'+x).join(', ')} · permanecen ${g.p.split('').map((b,i)=>b==='-'?'':vars()[i]+'='+b).filter(Boolean).join(', ')}</span></div></div>`});$('#groupsList').innerHTML=h||'<p class="note">No se necesitan grupos.</p>';renderMap();lastGroups.forEach((g,k)=>g.covers.forEach(i=>{let el=document.querySelector(`.cell[data-i="${i}"]`);if(el&&values[i]!=='0'){el.classList.add('grouped');el.style.setProperty('--group',colors[k%colors.length])}}))}
function renderTruth(){let h='<table><thead><tr>'+vars().map(v=>`<th>${v}</th>`).join('')+'<th>F</th></tr></thead><tbody>';values.forEach((v,i)=>h+='<tr>'+bits(i).split('').map(x=>`<td>${x}</td>`).join('')+`<td><b>${v}</b></td></tr>`);$('#truthTable').innerHTML=h+'</tbody></table>'}
function hideResults(){$('#results').classList.add('hidden');document.querySelectorAll('.step')[2].classList.remove('active')}
document.querySelectorAll('#varPicker button').forEach(b=>b.onclick=()=>{n=+b.dataset.n;values=Array(2**n).fill('0');document.querySelectorAll('#varPicker button').forEach(x=>x.classList.toggle('selected',x===b));renderMap();hideResults()});
$('#clearBtn').onclick=()=>{values.fill('0');$('#mintermInput').value='';renderMap();hideResults()};
$('#exampleBtn').onclick=()=>{values.fill('0');(n===2?[0,1,3]:n===3?[0,2,3,6,7]:[0,2,5,7,8,10,13,15]).forEach(i=>values[i]='1');renderMap();solve()};
$('#applyMinterms').onclick=()=>{values.fill('0');$('#mintermInput').value.split(/[ ,;]+/).map(Number).filter(x=>Number.isInteger(x)&&x>=0&&x<2**n).forEach(i=>values[i]='1');renderMap();hideResults()};
$('#solveBtn').onclick=solve;$('#copyBtn').onclick=async()=>{await navigator.clipboard.writeText('F = '+$('#sopResult').textContent);$('#savingBadge').textContent='Resultado copiado';setTimeout(()=>$('#savingBadge').textContent='',1800)};$('#themeBtn').onclick=()=>{document.body.classList.toggle('dark');$('#themeBtn').textContent=document.body.classList.contains('dark')?'☀':'☾'};renderMap();
